def page(title, desc, canonical, body, schema=None):
    schema = schema or {"@context":"https://schema.org","@type":"TravelAgency","name":"On A Trip Holidays","url":base,"telephone":"+91 91828 94146"}
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><link rel="canonical" href="{canonical}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:site_name" content="On A Trip Holidays"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><link rel="stylesheet" href="style.css"></head><body>{nav}{body}{footer}</body></html>'''

def hero(kicker,h1,intro,cta='View Packages'):
    return f'''<section class="hero"><div class="hero-copy"><div class="eyebrow">{kicker}</div><h1>{h1}</h1><p>{intro}</p><div class="hero-actions"><a class="btn" href="packages.html">{cta}</a><a class="btn secondary" href="https://wa.me/919182894146?text=Hi%20On%20A%20Trip%20Holidays%2C%20I%20want%20a%20custom%20trip">Plan My Trip</a></div></div></section>'''

def faq(items):
    return '<section class="section"><div class="head"><div><div class="eyebrow">FAQ</div><h2>Frequently asked questions</h2></div></div><div class="faq-grid">'+''.join(f'<details><summary>{html.escape(q)}</summary><p>{html.escape(a)}</p></details>' for q,a in items)+'</div></section>'

